{slug:"coconut-matcha-rice-pudding",title:"Coconut Matcha Rice Pudding",subtitle:"Creamy, green, comforting.",story:"Cooking short-grain rice in coconut milk creates a luscious pudding. Whisking in matcha adds a vibrant color and earthy finish.",category:"Desserts",tags:["Vegan","Gluten-Free"],allergens:[],difficulty:"Easy",prepTime:"5 min",cookTime:"30 min",servings:4,spiceLevel:0,umamiLevel:1,origin:"Asia",heroImage:snackBitesHero,thumbImage:snackBitesHero,ingredients:[{qty:"1",unit:"cup",item:"sushi rice"},{qty:"2",unit:"cans",item:"coconut milk"},{qty:"1",unit:"tbsp",item:"matcha"},{qty:"1/2",unit:"cup",item:"sugar"}],method:[{step:1,text:"Rinse the sushi rice thoroughly to remove excess surface starch."},{step:2,text:"Simmer the rice gently in the coconut milk until tender."},{step:3,text:"Stir in sugar during the last five minutes of cooking."},{step:4,text:"Whisk matcha with a splash of water and stir into the pudding."},{step:5,text:"Serve warm or chilled, garnished with toasted coconut flakes."}],chefNotes:"Stir frequently while simmering to prevent the rice from scorching on the bottom.",pairing:"Hot tea",mealSlots:["dessert"],healthy:true}
