{slug:"horchata-matcha-latte",title:"Horchata Matcha Latte",subtitle:"Earthy, creamy, spiced iced drink.",story:"The rich, cinnamon-laced sweetness of horchata forms the base, while a potent shot of whisked matcha floats on top.",category:"Drinks",tags:["Vegan","Gluten-Free"],allergens:[],difficulty:"Easy",prepTime:"5 min",cookTime:"0 min",servings:1,spiceLevel:0,umamiLevel:1,origin:"Oaxaca x Kyoto",heroImage:snackDipsHero,thumbImage:snackDipsHero,ingredients:[{qty:"1",unit:"cup",item:"horchata"},{qty:"1",unit:"tsp",item:"matcha"},{qty:"1",unit:"cup",item:"ice"}],method:[{step:1,text:"Fill a tall glass to the brim with large ice cubes."},{step:2,text:"Pour chilled horchata over the ice, leaving room at the top."},{step:3,text:"Whisk matcha powder with hot water until fully frothed."},{step:4,text:"Slowly pour the hot matcha shot over the horchata to layer it."},{step:5,text:"Serve immediately with a straw, stirring before drinking."}],chefNotes:"Pouring the matcha directly over an ice cube helps maintain the visual layers.",pairing:"Churros",mealSlots:["snack","breakfast"],healthy:true},
{slug:"jalapeno-margarita-yuzu",title:"Jalapeño Margarita",subtitle:"Spicy citrus refreshment.",story:"Replacing hard-to-find yuzu with a mix of lime and grapefruit zest mimics its floral aroma perfectly. Jalapeño adds a sharp bite.",category:"Drinks",tags:["Vegan","Gluten-Free"],allergens:[],difficulty:"Easy",prepTime:"5 min",cookTime:"0 min",servings:1,spiceLevel:2,umamiLevel:1,origin:"Mexico x Japan",heroImage:snackDipsHero,thumbImage:snackDipsHero,ingredients:[{qty:"2",unit:"oz",item:"tequila"},{qty:"1",unit:"oz",item:"lime juice"},{qty:"3",unit:"slices",item:"jalapeño"},{qty:"1",unit:"pinch",item:"grapefruit zest"}],method:[{step:1,text:"Muddle the jalapeño slices in the bottom of a cocktail shaker."},{step:2,text:"Add tequila, lime juice, and grapefruit zest to the shaker."},{step:3,text:"Fill with ice and shake vigorously for 15 seconds."},{step:4,text:"Strain over fresh ice into a rocks glass."},{step:5,text:"Garnish with a salted rim and an extra jalapeño slice."}],chefNotes:"Remove jalapeño seeds before muddling if you prefer a milder drink.",pairing:"Chips and salsa",mealSlots:["snack","dinner"],healthy:true},
{slug:"tamarind-agua-fresca",title:"Tamarind Agua Fresca",subtitle:"Tart, deeply refreshing.",story:"Boiling raw tamarind pods extracts their intense, sour flavor. Diluted with water and sweetened, it is the ultimate thirst quencher.",category:"Drinks",tags:["Vegan","Gluten-Free"],allergens:[],difficulty:"Medium",prepTime:"10 min",cookTime:"20 min",servings:4,spiceLevel:0,umamiLevel:1,origin:"Mexico",heroImage:snackDipsHero,thumbImage:snackDipsHero,ingredients:[{qty:"10",unit:"",item:"tamarind pods"},{qty:"4",unit:"cups",item:"water"},{qty:"1/4",unit:"cup",item:"sugar"}],method:[{step:1,text:"Peel the hard outer shell off the tamarind pods."},{step:2,text:"Boil the sticky pulp in water until it softens completely."},{step:3,text:"Mash the pulp through a fine strainer to remove seeds and fibers."},{step:4,text:"Mix the extracted pure liquid with cold water and sugar."},{step:5,text:"Serve over ice to cut the intense sweet-sour profile."}],chefNotes:"Using whole pods provides a brighter flavor than pre-made concentrate.",pairing:"Tacos",mealSlots:["lunch","dinner"],healthy:true},
{slug:"matcha-arnold-palmer",title:"Matcha Arnold Palmer",subtitle:"Green tea and lemonade.",story:"Replacing traditional black tea with iced matcha brings a grassy, vibrant green contrast to the tart, sweet lemonade.",category:"Drinks",tags:["Vegan","Gluten-Free"],allergens:[],difficulty:"Easy",prepTime:"5 min",cookTime:"0 min",servings:1,spiceLevel:0,umamiLevel:1,origin:"USA x Japan",heroImage:snackDipsHero,thumbImage:snackDipsHero,ingredients:[{qty:"1/2",unit:"cup",item:"lemonade"},{qty:"1/2",unit:"cup",item:"iced matcha"},{qty:"1",unit:"cup",item:"ice"}],method:[{step:1,text:"Whisk matcha powder in cold water until completely smooth."},{step:2,text:"Fill a tall glass with crushed ice."},{step:3,text:"Pour the lemonade in first to act as the heavy base."},{step:4,text:"Float the green matcha gently over the lemonade."},{step:5,text:"Stir immediately before drinking to combine the flavors."}],chefNotes:"Freshly squeezed lemonade makes a massive difference here.",pairing:"Sandwich",mealSlots:["lunch"],healthy:true},
{slug:"chamoy-michelada",title:"Chamoy Michelada",subtitle:"Salty, spicy beer cocktail.",story:"Coating the rim of a cold glass in chamoy and Tajín before pouring in a lime-spiked Mexican lager creates a savory, thirst-quenching masterpiece.",category:"Drinks",tags:["Dairy-Free"],allergens:["gluten","soy"],difficulty:"Easy",prepTime:"5 min",cookTime:"0 min",servings:1,spiceLevel:1,umamiLevel:2,origin:"Mexico",heroImage:snackDipsHero,thumbImage:snackDipsHero,ingredients:[{qty:"1",unit:"bottle",item:"Mexican lager"},{qty:"1",unit:"oz",item:"lime juice"},{qty:"2",unit:"tbsp",item:"chamoy"},{qty:"1",unit:"tbsp",item:"Tajín"}],method:[{step:1,text:"Dip the rim of a pint glass heavily into the chamoy sauce."},{step:2,text:"Press the sticky rim into a plate of Tajín to coat it."},{step:3,text:"Add a pinch of salt and the fresh lime juice to the glass."},{step:4,text:"Slowly pour the cold lager over the lime juice to prevent foaming."},{step:5,text:"Serve immediately while the beer is ice cold."}],chefNotes:"Do not add ice; simply use the coldest beer possible.",pairing:"Ceviche",mealSlots:["lunch","dinner"],healthy:false},
{slug:"mezcal-hibiscus-tonic",title:"Mezcal Hibiscus Tonic",subtitle:"Smoky and floral.",story:"The deep smoke of artisanal mezcal pairs beautifully with the tart, floral notes of brewed hibiscus tea. Tonic water adds bubbles and bitter quinine.",category:"Drinks",tags:["Vegan","Gluten-Free"],allergens:[],difficulty:"Easy",prepTime:"5 min",cookTime:"0 min",servings:1,spiceLevel:0,umamiLevel:1,origin:"Oaxaca",heroImage:snackDipsHero,thumbImage:snackDipsHero,ingredients:[{qty:"2",unit:"oz",item:"mezcal"},{qty:"1",unit:"oz",item:"hibiscus tea"},{qty:"3",unit:"oz",item:"tonic water"}],method:[{step:1,text:"Brew strong hibiscus tea and let it cool completely."},{step:2,text:"Fill a highball glass with large ice cubes."},{step:3,text:"Pour in the mezcal and the chilled hibiscus tea."},{step:4,text:"Top off the glass with premium tonic water."},{step:5,text:"Garnish with a lime wheel and stir gently."}],chefNotes:"A high-quality tonic water is essential, as cheap ones are too sweet.",pairing:"Guacamole",mealSlots:["dinner"],healthy:true},
{slug:"agua-fresca-watermelon-shiso",title:"Watermelon Shiso Agua Fresca",subtitle:"Sweet melon with herbal mint notes.",story:"Watermelon agua fresca is ubiquitous. Blending in fresh shiso leaves adds a complex, minty-basil aroma that elevates the drink.",category:"Drinks",tags:["Vegan","Gluten-Free"],allergens:[],difficulty:"Easy",prepTime:"10 min",cookTime:"0 min",servings:4,spiceLevel:0,umamiLevel:1,origin:"Mexico x Japan",heroImage:snackDipsHero,thumbImage:snackDipsHero,ingredients:[{qty:"4",unit:"cups",item:"watermelon chunks"},{qty:"4",unit:"leaves",item:"shiso"},{qty:"1",unit:"tbsp",item:"lime juice"}],method:[{step:1,text:"Remove all seeds from the watermelon chunks to ensure a smooth drink."},{step:2,text:"Place melon, shiso leaves, and lime juice in a blender."},{step:3,text:"Blend on high until the mixture is completely liquefied."},{step:4,text:"Strain through a fine mesh sieve to remove any fibrous pulp."},{step:5,text:"Serve over ice, garnished with a whole shiso leaf."}],chefNotes:"If you cannot find shiso, a mix of fresh mint and basil mimics it well.",pairing:"Spicy tacos",mealSlots:["lunch"],healthy:true},
{slug:"miso-whiskey-sour",title:"Miso Whiskey Sour",subtitle:"A classic cocktail with savory depth.",story:"Dissolving a tiny amount of white miso into simple syrup creates a savory backbone that perfectly complements the oak of bourbon.",category:"Drinks",tags:["Dairy-Free","Gluten-Free"],allergens:["soy"],difficulty:"Medium",prepTime:"10 min",cookTime:"0 min",servings:1,spiceLevel:0,umamiLevel:2,origin:"USA x Japan",heroImage:snackDipsHero,thumbImage:snackDipsHero,ingredients:[{qty:"2",unit:"oz",item:"bourbon"},{qty:"1",unit:"oz",item:"lemon juice"},{qty:"1/2",unit:"oz",item:"miso simple syrup"},{qty:"1",unit:"",item:"egg white"}],method:[{step:1,text:"Whisk equal parts hot water, sugar, and a pinch of miso to make the syrup."},{step:2,text:"Combine bourbon, lemon juice, syrup, and egg white in a shaker."},{step:3,text:"Dry shake vigorously without ice to foam the egg white."},{step:4,text:"Add ice and shake again to chill the drink."},{step:5,text:"Strain into a coupe glass and garnish with a lemon peel."}],chefNotes:"The dry shake is mandatory for a thick, luxurious foam.",pairing:"Pork skewers",mealSlots:["dinner"],healthy:false},
{slug:"tajin-bloody-mary-miso",title:"Tajín Bloody Mary",subtitle:"Spicy tomato with umami punch.",story:"Upgrading a bloody mary by using Tajín on the rim and a dash of miso in the tomato juice creates the ultimate savory brunch cocktail.",category:"Drinks",tags:["Dairy-Free"],allergens:["soy"],difficulty:"Easy",prepTime:"5 min",cookTime:"0 min",servings:1,spiceLevel:2,umamiLevel:3,origin:"Mexico x USA",heroImage:snackDipsHero,thumbImage:snackDipsHero,ingredients:[{qty:"2",unit:"oz",item:"vodka"},{qty:"4",unit:"oz",item:"tomato juice"},{qty:"1",unit:"tsp",item:"white miso"},{qty:"1",unit:"tbsp",item:"Tajín"}],method:[{step:1,text:"Whisk the miso into a small splash of hot water to dissolve."},{step:2,text:"Rim a tall glass with lime juice and Tajín."},{step:3,text:"Combine vodka, tomato juice, and the dissolved miso in the glass."},{step:4,text:"Add ice and stir well to combine the savory elements."},{step:5,text:"Garnish with a celery stalk and a pickled jalapeño."}],chefNotes:"The miso replaces the traditional Worcestershire sauce, offering a cleaner umami.",pairing:"Eggs benedict",mealSlots:["breakfast","lunch"],healthy:true},
{slug:"horchata-cold-brew-float",title:"Horchata Cold Brew Float",subtitle:"Caffeine and cinnamon.",story:"Pouring intense, bitter cold brew coffee over a scoop of horchata ice cream creates a creamy, melting morning treat.",category:"Drinks",tags:["Vegetarian","Gluten-Free"],allergens:["dairy"],difficulty:"Easy",prepTime:"5 min",cookTime:"0 min",servings:1,spiceLevel:0,umamiLevel:1,origin:"Mexico x USA",heroImage:snackDipsHero,thumbImage:snackDipsHero,ingredients:[{qty:"1",unit:"cup",item:"cold brew coffee"},{qty:"1",unit:"scoop",item:"horchata ice cream"}],method:[{step:1,text:"Brew a strong batch of cold brew coffee and chill it."},{step:2,text:"Place a large, firm scoop of horchata ice cream in a glass."},{step:3,text:"Slowly pour the cold brew over the ice cream."},{step:4,text:"Allow the ice cream to begin melting into the coffee."},{step:5,text:"Serve with a spoon and a straw for easy consumption."}],chefNotes:"Do not add ice, as it will dilute the melting cream.",pairing:"Pan dulce",mealSlots:["breakfast","snack"],healthy:false},
{slug:"matcha-mojito",title:"Matcha Mojito",subtitle:"Mint, lime, rum, and green tea.",story:"The grassy notes of matcha pair brilliantly with fresh mint and white rum, creating a vivid green, highly refreshing cocktail.",category:"Drinks",tags:["Vegan","Gluten-Free"],allergens:[],difficulty:"Easy",prepTime:"5 min",cookTime:"0 min",servings:1,spiceLevel:0,umamiLevel:1,origin:"Cuba x Japan",heroImage:snackDipsHero,thumbImage:snackDipsHero,ingredients:[{qty:"2",unit:"oz",item:"white rum"},{qty:"1",unit:"tsp",item:"matcha"},{qty:"1",unit:"oz",item:"lime juice"},{qty:"6",unit:"leaves",item:"mint"},{qty:"2",unit:"oz",item:"club soda"}],method:[{step:1,text:"Muddle the mint leaves lightly with lime juice in a glass."},{step:2,text:"Whisk matcha into the white rum until dissolved."},{step:3,text:"Pour the green rum mixture over the muddled mint."},{step:4,text:"Fill the glass with crushed ice to the top."},{step:5,text:"Top with club soda and stir gently to lift the mint."}],chefNotes:"Do not shred the mint when muddling; just press it to release the oils.",pairing:"Fish tacos",mealSlots:["dinner"],healthy:true},
{slug:"cucumber-jalapeno-seltzer",title:"Cucumber Jalapeño Seltzer",subtitle:"Crisp, cooling, with a bite.",story:"A mocktail that relies on the intense cooling power of cucumber water, punctuated by the sharp heat of fresh jalapeño.",category:"Drinks",tags:["Vegan","Gluten-Free"],allergens:[],difficulty:"Easy",prepTime:"10 min",cookTime:"0 min",servings:1,spiceLevel:2,umamiLevel:1,origin:"Mexico",heroImage:snackDipsHero,thumbImage:snackDipsHero,ingredients:[{qty:"2",unit:"oz",item:"cucumber juice"},{qty:"2",unit:"slices",item:"jalapeño"},{qty:"4",unit:"oz",item:"sparkling water"}],method:[{step:1,text:"Juice a fresh cucumber and strain out the pulp."},{step:2,text:"Muddle jalapeño slices in the bottom of a glass."},{step:3,text:"Pour the crisp cucumber juice over the peppers."},{step:4,text:"Fill with ice and top generously with sparkling water."},{step:5,text:"Stir and garnish with a cucumber ribbon."}],chefNotes:"Leave the jalapeño seeds in for a much spicier drink.",pairing:"Chips and guacamole",mealSlots:["lunch","snack"],healthy:true},
{slug:"hibiscus-iced-tea-miso",title:"Hibiscus Iced Tea",subtitle:"Floral tea sweetened with miso honey.",story:"Agua de jamaica is famously tart. Sweetening it with honey that has been blended with white miso adds an addictive savory finish.",category:"Drinks",tags:["Vegetarian","Gluten-Free"],allergens:["soy"],difficulty:"Easy",prepTime:"5 min",cookTime:"15 min",servings:4,spiceLevel:0,umamiLevel:2,origin:"Mexico x Japan",heroImage:snackDipsHero,thumbImage:snackDipsHero,ingredients:[{qty:"1/2",unit:"cup",item:"dried hibiscus flowers"},{qty:"4",unit:"cups",item:"water"},{qty:"2",unit:"tbsp",item:"honey"},{qty:"1",unit:"tsp",item:"white miso"}],method:[{step:1,text:"Boil the hibiscus flowers in water for 15 minutes to extract flavor."},{step:2,text:"Strain out the flowers and let the deep red tea cool."},{step:3,text:"Whisk the honey and white miso together until smooth."},{step:4,text:"Stir the savory honey into the warm tea until dissolved."},{step:5,text:"Serve over abundant ice with a squeeze of fresh lime."}],chefNotes:"The miso must be dissolved while the tea is still warm to prevent clumping.",pairing:"Chicken tinga",mealSlots:["lunch"],healthy:true},
{slug:"tamarind-paloma",title:"Tamarind Paloma",subtitle:"Grapefruit soda and sour tamarind.",story:"The classic Paloma uses grapefruit soda. Adding a spoonful of tamarind concentrate deepens the color and amps up the tartness dramatically.",category:"Drinks",tags:["Vegan","Gluten-Free"],allergens:[],difficulty:"Easy",prepTime:"5 min",cookTime:"0 min",servings:1,spiceLevel:0,umamiLevel:1,origin:"Mexico",heroImage:snackDipsHero,thumbImage:snackDipsHero,ingredients:[{qty:"2",unit:"oz",item:"tequila blanco"},{qty:"1",unit:"tbsp",item:"tamarind concentrate"},{qty:"4",unit:"oz",item:"grapefruit soda"},{qty:"1",unit:"pinch",item:"salt"}],method:[{step:1,text:"Dissolve the tamarind concentrate into the tequila."},{step:2,text:"Add a pinch of salt to balance the sour notes."},{step:3,text:"Pour the mixture over ice in a tall glass."},{step:4,text:"Top off with bubbly grapefruit soda."},{step:5,text:"Garnish with a grapefruit wedge and serve."}],chefNotes:"Use a Mexican grapefruit soda like Squirt for the most authentic flavor.",pairing:"Pork carnitas",mealSlots:["dinner"],healthy:true},
{slug:"matcha-lemonade",title:"Sparkling Matcha Lemonade",subtitle:"Bubbly, tart, and grassy.",story:"Combining fresh lemonade with sparkling water and a float of ceremonial matcha creates a visually stunning, highly refreshing afternoon drink.",category:"Drinks",tags:["Vegan","Gluten-Free"],allergens:[],difficulty:"Easy",prepTime:"5 min",cookTime:"0 min",servings:1,spiceLevel:0,umamiLevel:1,origin:"USA x Japan",heroImage:snackDipsHero,thumbImage:snackDipsHero,ingredients:[{qty:"2",unit:"oz",item:"lemon juice"},{qty:"1",unit:"oz",item:"simple syrup"},{qty:"1",unit:"tsp",item:"matcha"},{qty:"3",unit:"oz",item:"sparkling water"}],method:[{step:1,text:"Mix lemon juice and simple syrup to form a concentrated base."},{step:2,text:"Pour the base over ice and top with sparkling water."},{step:3,text:"Whisk matcha with a small amount of warm water until frothy."},{step:4,text:"Pour the matcha slowly over the sparkling lemonade to layer."},{step:5,text:"Stir vigorously right before drinking to combine."}],chefNotes:"Using warm water to whisk the matcha ensures it doesn't clump.",pairing:"Salad",mealSlots:["lunch"],healthy:true},
{slug:"agua-fresca-cucumber-lime-shiso",title:"Cucumber Lime Shiso",subtitle:"The ultimate cooler.",story:"Blending cucumber and lime into a classic agua fresca, elevated by the aromatic mint-basil notes of fresh shiso leaves.",category:"Drinks",tags:["Vegan","Gluten-Free"],allergens:[],difficulty:"Easy",prepTime:"10 min",cookTime:"0 min",servings:4,spiceLevel:0,umamiLevel:1,origin:"Mexico x Japan",heroImage:snackDipsHero,thumbImage:snackDipsHero,ingredients:[{qty:"2",unit:"",item:"cucumbers"},{qty:"1/4",unit:"cup",item:"lime juice"},{qty:"6",unit:"leaves",item:"shiso"}],method:[{step:1,text:"Peel and roughly chop the cucumbers to remove bitter skins."},{step:2,text:"Blend the cucumber, lime juice, and shiso leaves with water."},{step:3,text:"Strain the bright green liquid through a fine sieve."},{step:4,text:"Sweeten lightly with agave nectar to taste."},{step:5,text:"Serve over ice to maximize the cooling effect."}],chefNotes:"English cucumbers are best as they have fewer bitter seeds.",pairing:"Spicy tuna bites",mealSlots:["lunch"],healthy:true},
{slug:"ponzu-spritz",title:"Ponzu Citrus Spritz",subtitle:"A savory, tart mocktail.",story:"A daring mocktail that uses a few drops of citrus-soy ponzu to add a deeply savory, complex backbone to a standard citrus spritz.",category:"Drinks",tags:["Dairy-Free"],allergens:["soy","gluten"],difficulty:"Medium",prepTime:"5 min",cookTime:"0 min",servings:1,spiceLevel:0,umamiLevel:2,origin:"Osaka",heroImage:snackDipsHero,thumbImage:snackDipsHero,ingredients:[{qty:"1",unit:"oz",item:"orange juice"},{qty:"1/2",unit:"tsp",item:"ponzu sauce"},{qty:"4",unit:"oz",item:"tonic water"}],method:[{step:1,text:"Combine fresh orange juice and ponzu sauce in a glass."},{step:2,text:"Add a large cube of ice to keep the drink cold without diluting."},{step:3,text:"Pour the tonic water slowly over the ice to maintain carbonation."},{step:4,text:"Stir very gently to lift the heavy ponzu from the bottom."},{step:5,text:"Garnish with an orange twist."}],chefNotes:"Use a high-quality ponzu; cheap ones are too heavily salted.",pairing:"Edamame",mealSlots:["snack"],healthy:true},
{slug:"chamoy-tajin-mangonada",title:"Chamoy Tajín Mangonada",subtitle:"Frozen mango and chili sorbet.",story:"A classic Mexican street treat. Frozen mango blended into a thick slush, layered heavily with sour chamoy and spicy Tajín.",category:"Drinks",tags:["Vegan","Gluten-Free"],allergens:[],difficulty:"Easy",prepTime:"10 min",cookTime:"0 min",servings:2,spiceLevel:2,umamiLevel:1,origin:"Mexico",heroImage:snackDipsHero,thumbImage:snackDipsHero,ingredients:[{qty:"2",unit:"cups",item:"frozen mango"},{qty:"1/4",unit:"cup",item:"chamoy"},{qty:"1",unit:"tbsp",item:"Tajín"}],method:[{step:1,text:"Blend frozen mango with a splash of water until it forms a thick slush."},{step:2,text:"Squeeze a heavy ring of chamoy around the inside of a cup."},{step:3,text:"Spoon in half the mango slush, then add more chamoy and Tajín."},{step:4,text:"Top with the remaining mango slush."},{step:5,text:"Serve with a tamarind candy straw for the authentic experience."}],chefNotes:"You must use frozen mango to achieve the thick, sorbet-like texture.",pairing:"Tortilla chips",mealSlots:["snack"],healthy:true},
{slug:"miso-hot-toddy",title:"Miso Honey Hot Toddy",subtitle:"Warming, savory winter drink.",story:"A hot toddy cures everything. Adding a dash of white miso to the honey provides a soothing, brothy quality that warms the soul.",category:"Drinks",tags:["Dairy-Free","Gluten-Free"],allergens:["soy"],difficulty:"Easy",prepTime:"5 min",cookTime:"5 min",servings:1,spiceLevel:0,umamiLevel:2,origin:"USA x Japan",heroImage:snackDipsHero,thumbImage:snackDipsHero,ingredients:[{qty:"2",unit:"oz",item:"whiskey"},{qty:"1",unit:"tbsp",item:"honey"},{qty:"1/2",unit:"tsp",item:"white miso"},{qty:"1",unit:"oz",item:"lemon juice"}],method:[{step:1,text:"Whisk the white miso and honey together in the bottom of a mug."},{step:2,text:"Pour in the fresh lemon juice and whiskey."},{step:3,text:"Top with boiling water and stir until the miso-honey dissolves."},{step:4,text:"Drop in a cinnamon stick for aromatic spice."},{step:5,text:"Sip slowly while hot to soothe the throat."}],chefNotes:"Ensure the water is boiling hot so the miso dissolves entirely.",pairing:"Shortbread",mealSlots:["snack"],healthy:true},
{slug:"green-tea-horchata",title:"Green Tea Horchata",subtitle:"Toasted rice and matcha.",story:"Traditional horchata relies on toasted rice. Blending it with roasted green tea (hojicha) or matcha bridges the two rice cultures seamlessly.",category:"Drinks",tags:["Vegan","Gluten-Free"],allergens:[],difficulty:"Medium",prepTime:"10 min",cookTime:"0 min",servings:4,spiceLevel:0,umamiLevel:1,origin:"Mexico x Japan",heroImage:snackDipsHero,thumbImage:snackDipsHero,ingredients:[{qty:"1",unit:"cup",item:"white rice"},{qty:"1",unit:"tbsp",item:"matcha"},{qty:"4",unit:"cups",item:"water"},{qty:"1",unit:"stick",item:"cinnamon"}],method:[{step:1,text:"Soak the rice and cinnamon stick in water overnight to soften."},{step:2,text:"Blend the rice, water, and cinnamon until completely liquefied."},{step:3,text:"Strain through a cheesecloth to remove all gritty rice particles."},{step:4,text:"Whisk in the matcha powder and sweeten to taste."},{step:5,text:"Serve over ice to keep the dairy-free milk refreshing."}],chefNotes:"Do not skip the overnight soak, or the rice will not blend smoothly.",pairing:"Almond cookies",mealSlots:["breakfast","snack"],healthy:true},
{slug:"spicy-mango-margarita",title:"Spicy Mango Margarita",subtitle:"Sweet fruit, fiery finish.",story:"Blending fresh mango puree with tequila and habanero creates a viscous, intensely flavorful cocktail that balances fire and ice.",category:"Drinks",tags:["Vegan","Gluten-Free"],allergens:[],difficulty:"Easy",prepTime:"5 min",cookTime:"0 min",servings:1,spiceLevel:3,umamiLevel:1,origin:"Mexico",heroImage:snackDipsHero,thumbImage:snackDipsHero,ingredients:[{qty:"2",unit:"oz",item:"tequila"},{qty:"2",unit:"oz",item:"mango puree"},{qty:"1",unit:"slice",item:"habanero"}],method:[{step:1,text:"Muddle the highly spicy habanero slice carefully in the shaker."},{step:2,text:"Add the sweet mango puree, tequila, and lime juice."},{step:3,text:"Shake with ice until the tin is frosted on the outside."},{step:4,text:"Strain over fresh ice to remove the pepper seeds."},{step:5,text:"Garnish with a chili-salt rim to enhance the sweet mango."}],chefNotes:"Wash your hands immediately after muddling the habanero.",pairing:"Pork belly",mealSlots:["dinner"],healthy:true},
{slug:"matcha-rum-cocktail",title:"Matcha Rum Cocktail",subtitle:"Tropical green tea.",story:"White rum and coconut water provide a tropical base that perfectly supports the earthy bitterness of ceremonial matcha.",category:"Drinks",tags:["Vegan","Gluten-Free"],allergens:[],difficulty:"Easy",prepTime:"5 min",cookTime:"0 min",servings:1,spiceLevel:0,umamiLevel:1,origin:"Caribbean x Japan",heroImage:snackDipsHero,thumbImage:snackDipsHero,ingredients:[{qty:"2",unit:"oz",item:"white rum"},{qty:"3",unit:"oz",item:"coconut water"},{qty:"1",unit:"tsp",item:"matcha"}],method:[{step:1,text:"Whisk the matcha into the white rum until it dissolves."},{step:2,text:"Pour the vibrant green rum into a glass filled with ice."},{step:3,text:"Top with the sweet, hydrating coconut water."},{step:4,text:"Squeeze a fresh lime wedge over the top."},{step:5,text:"Stir well to combine the earthy and tropical notes."}],chefNotes:"Coconut water naturally sweetens the drink, so no syrup is needed.",pairing:"Fruit salad",mealSlots:["lunch"],healthy:true},
{slug:"tamarind-sparkling-limeade",title:"Tamarind Sparkling Limeade",subtitle:"Fizzy, sour, perfect.",story:"A simple upgrade to standard limeade. Tamarind concentrate adds a brown hue and a deep, sour complexity that shines with carbonation.",category:"Drinks",tags:["Vegan","Gluten-Free"],allergens:[],difficulty:"Easy",prepTime:"5 min",cookTime:"0 min",servings:1,spiceLevel:0,umamiLevel:1,origin:"Mexico",heroImage:snackDipsHero,thumbImage:snackDipsHero,ingredients:[{qty:"1",unit:"oz",item:"lime juice"},{qty:"1",unit:"tbsp",item:"tamarind concentrate"},{qty:"4",unit:"oz",item:"sparkling water"}],method:[{step:1,text:"Mix the lime juice, tamarind concentrate, and a dash of syrup."},{step:2,text:"Pour the sour base into a tall glass over ice."},{step:3,text:"Top with sparkling water to provide necessary fizz."},{step:4,text:"Stir gently to integrate the heavy tamarind from the bottom."},{step:5,text:"Garnish with a lime wheel and serve immediately."}],chefNotes:"Adjust the syrup based on how sour your tamarind concentrate is.",pairing:"Spicy wings",mealSlots:["snack"],healthy:true},
{slug:"mezcal-miso-old-fashioned",title:"Mezcal Miso Old Fashioned",subtitle:"Smoke, oak, and umami.",story:"Replacing whiskey with smoky mezcal and adding a dash of miso-infused agave nectar creates an aggressively flavorful, sipping cocktail.",category:"Drinks",tags:["Dairy-Free","Gluten-Free"],allergens:["soy"],difficulty:"Advanced",prepTime:"5 min",cookTime:"0 min",servings:1,spiceLevel:0,umamiLevel:2,origin:"Oaxaca x Japan",heroImage:snackDipsHero,thumbImage:snackDipsHero,ingredients:[{qty:"2",unit:"oz",item:"mezcal"},{qty:"1/4",unit:"oz",item:"agave nectar"},{qty:"1/4",unit:"tsp",item:"white miso"},{qty:"2",unit:"dashes",item:"bitters"}],method:[{step:1,text:"Whisk the white miso into the thick agave nectar until smooth."},{step:2,text:"Add the savory agave, bitters, and mezcal to a mixing glass."},{step:3,text:"Add a large block of ice and stir continuously for 30 seconds."},{step:4,text:"Strain into a rocks glass over a fresh, clear ice cube."},{step:5,text:"Express an orange peel over the top to add citrus oils."}],chefNotes:"Stirring for 30 seconds is crucial to properly chill and dilute the heavy spirits.",pairing:"Steak",mealSlots:["dinner"],healthy:true},
{slug:"jalapeno-cucumber-agua-fresca",title:"Jalapeño Cucumber Agua Fresca",subtitle:"Cooling with a spicy kick.",story:"The ultimate summer cooler. Cucumber water provides extreme hydration, while jalapeño slices offer a lingering, spicy finish.",category:"Drinks",tags:["Vegan","Gluten-Free"],allergens:[],difficulty:"Easy",prepTime:"10 min",cookTime:"0 min",servings:4,spiceLevel:2,umamiLevel:1,origin:"Mexico",heroImage:snackDipsHero,thumbImage:snackDipsHero,ingredients:[{qty:"2",unit:"",item:"cucumbers"},{qty:"1",unit:"",item:"jalapeño"},{qty:"4",unit:"cups",item:"water"}],method:[{step:1,text:"Blend the peeled cucumbers and water until smooth."},{step:2,text:"Strain the juice into a pitcher to remove the fibrous pulp."},{step:3,text:"Slice the jalapeño thinly and drop the rings into the pitcher."},{step:4,text:"Let steep in the fridge for an hour to infuse the heat."},{step:5,text:"Serve over ice for a profoundly refreshing drink."}],chefNotes:"The longer the jalapeño steeps, the spicier the drink becomes.",pairing:"Spicy ceviche",mealSlots:["lunch"],healthy:true}

